    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *v0 = (PyArrayObject *)PyArray_FROM_OTF(v0_o, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!data || !indices || !indptr || !v0) {
        Py_XDECREF(data); Py_XDECREF(indices); Py_XDECREF(indptr); Py_XDECREF(v0);
        return NULL;
