    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0;      /* LM */
    st.ido = 0;
    st.info = 1;       /* use resid as start */
    st.bmat = 0;       /* I */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    double *resid = (double *)malloc(sizeof(double) * n);
    double *v = (double *)calloc((size_t)n * ncv, sizeof(double)); /* C order matches scipy zeros((n,ncv)) */
    int *ipntr = (int *)calloc(14, sizeof(int));
    double *workd = (double *)calloc(3 * n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));
    memcpy(resid, PyArray_DATA(v0), sizeof(double) * n);

