# Easier path: return the raw state bytes + arrays, then in Python call ARNAUD_dneupd via ctypes
# with the same convention. If dneupd crashes too, the convention is wrong.
# First confirm dnaupd-only version still works (it did). Then call dneupd from Python ctypes
# so we can iterate on the signature without recompiling as much.

cat > fastarpack.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>
#include <stdlib.h>
#include <dlfcn.h>

typedef struct {
    double tol;
    double getv0_rnorm0;
    double aitr_betaj;
    double aitr_rnorm1;
    double aitr_wnorm;
    double aup2_rnorm;
    int which;
    int ido;
    int info;
    int bmat;
    int mode;
    int n;
    int ncv;
    int nev;
    int shift;
    int maxiter;
    int nconv;
    int iter;
    int np;
    int getv0_first;
    int getv0_iter;
    int getv0_itry;
    int getv0_orth;
    int aitr_iter;
    int aitr_j;
    int aitr_orth1;
    int aitr_orth2;
    int aitr_restart;
    int aitr_step3;
    int aitr_step4;
    int aitr_ierr;
    int aup2_initv;
    int aup2_iter;
    int aup2_getv0;
    int aup2_cnorm;
    int aup2_kplusp;
    int aup2_nev;
    int aup2_nev0;
    int aup2_np0;
    int aup2_numcnv;
    int aup2_update;
    int aup2_ushift;
} arnaud_state;

typedef void (*dnaupd_fn)(arnaud_state *state, double *resid, double *v, int n,
                          int *ipntr, double *workd, double *workl);
static dnaupd_fn DNAUPD = NULL;
static int ensure(void) {
    if (DNAUPD) return 0;
    DNAUPD = (dnaupd_fn)dlsym(RTLD_DEFAULT, "ARNAUD_dnaupd");
    if (!DNAUPD) { PyErr_SetString(PyExc_RuntimeError, "no dnaupd"); return -1; }
    return 0;
}
static void csr_matvec(int n, const double *data, const int *indices, const int *indptr,
                       const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int a = indptr[i], b = indptr[i+1];
        for (int j = a; j < b; j++) s += data[j] * x[indices[j]];
        y[i] = s;
    }
}
static PyObject *solve(PyObject *self, PyObject *args) {
    PyObject *data_o, *indices_o, *indptr_o, *v0_o;
    int k, ncv, maxiter; double tol;
    if (!PyArg_ParseTuple(args, "OOOiiidO", &data_o, &indices_o, &indptr_o, &k, &ncv, &maxiter, &tol, &v0_o))
        return NULL;
    if (ensure() < 0) return NULL;
    PyArrayObject *data = (PyArrayObject *)PyArray_FROM_OTF(data_o, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices = (PyArrayObject *)PyArray_FROM_OTF(indices_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *v0 = (PyArrayObject *)PyArray_FROM_OTF(v0_o, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!data || !indices || !indptr || !v0) {
        Py_XDECREF(data); Py_XDECREF(indices); Py_XDECREF(indptr); Py_XDECREF(v0);
        return NULL;
    }
    int n = (int)PyArray_DIM(v0, 0);
    arnaud_state st; memset(&st, 0, sizeof(st));
    st.tol = tol; st.which = 0; st.ido = 0; st.info = 1; st.bmat = 0; st.mode = 1;
    st.n = n; st.ncv = ncv; st.nev = k; st.shift = 1; st.maxiter = maxiter;

    npy_intp rd = n, vd[2] = {n, ncv}, id = 14, wd = 3*(npy_intp)n;
    int lworkl = 3 * ncv * (ncv + 2);
    npy_intp ld = lworkl;
    npy_intp sd = sizeof(arnaud_state);
    PyArrayObject *resid = (PyArrayObject *)PyArray_SimpleNew(1, &rd, NPY_DOUBLE);
    PyArrayObject *v = (PyArrayObject *)PyArray_ZEROS(2, vd, NPY_DOUBLE, 0);
    PyArrayObject *ipntr = (PyArrayObject *)PyArray_ZEROS(1, &id, NPY_INT32, 0);
    PyArrayObject *workd = (PyArrayObject *)PyArray_ZEROS(1, &wd, NPY_DOUBLE, 0);
    PyArrayObject *workl = (PyArrayObject *)PyArray_ZEROS(1, &ld, NPY_DOUBLE, 0);
    PyArrayObject *state = (PyArrayObject *)PyArray_ZEROS(1, &sd, NPY_UINT8, 0);
    memcpy(PyArray_DATA(resid), PyArray_DATA(v0), sizeof(double)*n);
    double *workd_p = (double *)PyArray_DATA(workd);
    int *ipntr_p = (int *)PyArray_DATA(ipntr);
    const double *Adata = (const double *)PyArray_DATA(data);
    const int *Aind = (const int *)PyArray_DATA(indices);
    const int *Aptr = (const int *)PyArray_DATA(indptr);
    int guard = 0, guard_max = maxiter * (ncv + 2) + 1000;
    while (guard++ < guard_max) {
        DNAUPD(&st, (double *)PyArray_DATA(resid), (double *)PyArray_DATA(v), n, ipntr_p, workd_p, (double *)PyArray_DATA(workl));
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5)
            csr_matvec(n, Adata, Aind, Aptr, workd_p + ipntr_p[0], workd_p + ipntr_p[1]);
        else if (ido == 2)
            memcpy(workd_p + ipntr_p[1], workd_p + ipntr_p[0], sizeof(double)*n);
        else if (ido == 4) {
            double *r = (double *)PyArray_DATA(resid);
            for (int i = 0; i < n; i++) r[i] = 1.0;
        } else break;
    }
    memcpy(PyArray_DATA(state), &st, sizeof(st));
    Py_DECREF(data); Py_DECREF(indices); Py_DECREF(indptr); Py_DECREF(v0); Py_DECREF(workd);
    PyObject *ret = Py_BuildValue("OOOO", v, workl, resid, state);
    Py_DECREF(v); Py_DECREF(workl); Py_DECREF(resid); Py_DECREF(state);
    return ret;
}
static PyMethodDef methods[] = {{"solve", solve, METH_VARARGS, ""}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastarpack", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastarpack(void) { import_array(); return PyModule_Create(&moduledef); }
